package bankverification

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net"
	"net/http"
	"net/url"
	"regexp"
	"strings"
	"time"

	"github.com/google/uuid"
)

var (
	countryPattern      = regexp.MustCompile(`^[A-Z]{2}$`)
	referencePattern    = regexp.MustCompile(`^bankref_[A-Za-z0-9_-]{8,100}$`)
	verificationPattern = regexp.MustCompile(`^[A-Za-z0-9_-]{8,128}$`)
	last4Pattern        = regexp.MustCompile(`^[0-9]{4}$`)
	bankSessionPattern  = regexp.MustCompile(`^[A-Za-z0-9_-]{16,160}$`)
)

// LinkRequest is generated by the owning service, never from client authority.
// AttemptID is persisted before Create and reused after uncertain responses.
type LinkRequest struct {
	Scope
	ApplicationRole string `json:"application_role"`
	AttemptID       string `json:"attempt_id"`
	ProviderSession string `json:"provider_session_id,omitempty"`
}

// LinkResult intentionally has no account-number or routing-secret fields.
// LaunchURL is a short-lived bearer capability: return it only to the owner,
// with no-store, and never persist it in the application database or logs.
type LinkResult struct {
	LinkRequest
	Status         string    `json:"status"`
	ExpiresAt      time.Time `json:"expires_at"`
	LaunchURL      string    `json:"launch_url,omitempty"`
	Account        *Account  `json:"account,omitempty"`
	VerificationID string    `json:"verification_id,omitempty"`
	VerifiedAt     time.Time `json:"verified_at,omitempty"`
}

// Linker explicitly starts the provider's hosted verification journey. It is
// separate from Verifier, whose lookup must remain free of new side effects.
// Create must be idempotent on scope/role/attempt; Resolve may reissue a launch
// URL. Cancel must be idempotent, including a session that already completed.
// With no ProviderSession, Cancel looks up/cancels the durable AttemptID; it
// must never start a new verification merely to cancel an interrupted one.
type Linker interface {
	Create(context.Context, LinkRequest) (LinkResult, error)
	Resolve(context.Context, LinkRequest) (LinkResult, error)
	Cancel(context.Context, LinkRequest) (LinkResult, error)
}

type unavailableLinker struct{}

func (unavailableLinker) Create(context.Context, LinkRequest) (LinkResult, error) {
	return LinkResult{}, ErrUnavailable
}
func (unavailableLinker) Resolve(context.Context, LinkRequest) (LinkResult, error) {
	return LinkResult{}, ErrUnavailable
}
func (unavailableLinker) Cancel(context.Context, LinkRequest) (LinkResult, error) {
	return LinkResult{}, ErrUnavailable
}
func UnavailableLinker() Linker { return unavailableLinker{} }

type LinkerConfig struct {
	Endpoint                 *url.URL
	Client                   *http.Client
	Token                    string
	Clock                    func() time.Time
	LaunchOrigins            []string
	AllowLoopbackHTTP        bool
	AllowPrivateEndpointHTTP bool
}

type HTTPLinker struct {
	endpoint url.URL
	client   http.Client
	token    string
	clock    func() time.Time
	origins  map[string]bool
}

func NewHTTPLinker(config LinkerConfig) (Linker, error) {
	if config.Endpoint == nil && config.Token == "" && len(config.LaunchOrigins) == 0 {
		return UnavailableLinker(), nil
	}
	u := config.Endpoint
	endpointAllowed := safeBankURL(u, config.AllowLoopbackHTTP)
	if !endpointAllowed && config.AllowPrivateEndpointHTTP && u != nil && u.Scheme == "http" {
		// Explicit development-only service traffic on a private Docker network.
		// This exception never applies to browser launch origins.
		host := u.Hostname()
		ip := net.ParseIP(host)
		endpointAllowed = (ip != nil && ip.IsPrivate() || host != "" && !strings.Contains(host, ".") && !strings.ContainsAny(host, ":%")) && safeBankURL(&url.URL{Scheme: "https", Host: u.Host, Path: u.Path, RawQuery: u.RawQuery, User: u.User, Fragment: u.Fragment, Opaque: u.Opaque, ForceQuery: u.ForceQuery}, false)
	}
	if u == nil || config.Client == nil || config.Clock == nil || config.Client.Timeout <= 0 || config.Client.Timeout > 10*time.Second ||
		len(config.Token) < 32 || len(config.Token) > 4096 || strings.TrimSpace(config.Token) != config.Token || strings.ContainsAny(config.Token, "\r\n") ||
		!endpointAllowed || (u.Path != "" && u.Path != "/") || u.RawQuery != "" || len(config.LaunchOrigins) < 1 || len(config.LaunchOrigins) > 8 {
		return nil, ErrUnavailable
	}
	origins := make(map[string]bool, len(config.LaunchOrigins))
	for _, origin := range config.LaunchOrigins {
		parsed, err := url.Parse(origin)
		if err != nil || !safeBankURL(parsed, config.AllowLoopbackHTTP) || parsed.Path != "" || parsed.RawQuery != "" || parsed.String() != origin {
			return nil, ErrUnavailable
		}
		origins[parsed.Scheme+"://"+parsed.Host] = true
	}
	client := *config.Client
	client.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	// A caller-supplied cookie jar must not leak browser/provider cookies into
	// the service-to-service API or retain provider Set-Cookie responses.
	client.Jar = nil
	return &HTTPLinker{endpoint: *u, client: client, token: config.Token, clock: config.Clock, origins: origins}, nil
}

func safeBankURL(u *url.URL, allowLoopbackHTTP bool) bool {
	if u == nil || u.Host == "" || u.User != nil || u.Opaque != "" || u.Fragment != "" || u.RawFragment != "" || u.ForceQuery ||
		strings.ContainsAny(u.String(), "\\\r\n\t") || strings.Contains(u.Host, "%") || u.Hostname() == "" {
		return false
	}
	if u.Scheme == "https" {
		return true
	}
	if u.Scheme != "http" || !allowLoopbackHTTP {
		return false
	}
	ip := net.ParseIP(u.Hostname())
	return strings.EqualFold(u.Hostname(), "localhost") || (ip != nil && ip.IsLoopback())
}

func validLinkRequest(request LinkRequest, sessionRequired bool) bool {
	return canonicalBankUUID(request.TenantID) && canonicalBankUUID(request.OwnerID) && countryPattern.MatchString(request.Country) &&
		(request.ApplicationRole == "VENDOR" || request.ApplicationRole == "RIDER") && canonicalBankUUID(request.AttemptID) &&
		((sessionRequired && bankSessionPattern.MatchString(request.ProviderSession)) || (!sessionRequired && request.ProviderSession == ""))
}

func canonicalBankUUID(value string) bool {
	id, err := uuid.Parse(value)
	return err == nil && id != uuid.Nil && id.String() == value
}

func (l *HTTPLinker) Create(ctx context.Context, request LinkRequest) (LinkResult, error) {
	return l.exchange(ctx, "", request)
}
func (l *HTTPLinker) Resolve(ctx context.Context, request LinkRequest) (LinkResult, error) {
	return l.exchange(ctx, ":resolve", request)
}
func (l *HTTPLinker) Cancel(ctx context.Context, request LinkRequest) (LinkResult, error) {
	return l.exchange(ctx, ":cancel", request)
}

func (l *HTTPLinker) exchange(ctx context.Context, action string, input LinkRequest) (LinkResult, error) {
	if !validLinkRequest(input, action != "" && !(action == ":cancel" && input.ProviderSession == "")) {
		return LinkResult{}, ErrRejected
	}
	destination := l.endpoint
	destination.Path = "/v1/bank-accounts/link-sessions" + action
	body, _ := json.Marshal(input)
	request, err := http.NewRequestWithContext(ctx, http.MethodPost, destination.String(), bytes.NewReader(body))
	if err != nil {
		return LinkResult{}, ErrUnavailable
	}
	request.Header.Set("Authorization", "Bearer "+l.token)
	request.Header.Set("Content-Type", "application/json")
	request.Header.Set("Accept", "application/json")
	request.Header.Set("Idempotency-Key", input.AttemptID)
	response, err := l.client.Do(request)
	if err != nil {
		return LinkResult{}, ErrUnavailable
	}
	defer response.Body.Close()
	if response.StatusCode == http.StatusNotFound || response.StatusCode == http.StatusForbidden || response.StatusCode == http.StatusUnprocessableEntity {
		return LinkResult{}, ErrRejected
	}
	contents, err := io.ReadAll(io.LimitReader(response.Body, 16385))
	if err != nil || len(contents) > 16384 || response.StatusCode != http.StatusOK {
		return LinkResult{}, ErrUnavailable
	}
	var result LinkResult
	decoder := json.NewDecoder(bytes.NewReader(contents))
	decoder.DisallowUnknownFields()
	if decoder.Decode(&result) != nil || decoder.Decode(&struct{}{}) != io.EOF {
		return LinkResult{}, ErrUnavailable
	}
	if !l.validResult(input, result, action) {
		return LinkResult{}, ErrRejected
	}
	return result, nil
}

func (l *HTTPLinker) validResult(input LinkRequest, result LinkResult, action string) bool {
	now := l.clock().UTC()
	if result.Scope != input.Scope || result.ApplicationRole != input.ApplicationRole || result.AttemptID != input.AttemptID ||
		!bankSessionPattern.MatchString(result.ProviderSession) || (input.ProviderSession != "" && result.ProviderSession != input.ProviderSession) ||
		result.ExpiresAt.IsZero() || result.ExpiresAt.After(now.Add(30*time.Minute)) {
		return false
	}
	if result.Status != "EXPIRED" && !result.ExpiresAt.After(now) {
		return false
	}
	if action == ":cancel" && result.Status != "CANCELLED" && result.Status != "VERIFIED" && result.Status != "DECLINED" && result.Status != "EXPIRED" {
		return false
	}
	if result.Status == "VERIFIED" {
		return result.LaunchURL == "" && result.Account != nil && referencePattern.MatchString(result.Account.Reference) &&
			last4Pattern.MatchString(result.Account.Last4) && len(strings.TrimSpace(result.Account.HolderName)) >= 3 && len(result.Account.HolderName) <= 200 &&
			len(result.Account.IFSC) <= 32 && !strings.ContainsAny(result.Account.HolderName+result.Account.IFSC, "\r\n\t") &&
			verificationPattern.MatchString(result.VerificationID) && !result.VerifiedAt.Before(now.Add(-15*time.Minute)) && !result.VerifiedAt.After(now.Add(time.Minute))
	}
	if result.Account != nil || result.VerificationID != "" || !result.VerifiedAt.IsZero() {
		return false
	}
	switch result.Status {
	case "AWAITING_USER":
		launch, err := url.Parse(result.LaunchURL)
		return err == nil && len(result.LaunchURL) <= 4096 && safeBankURL(launch, true) && l.origins[launch.Scheme+"://"+launch.Host] && launch.Path != ""
	case "VERIFYING", "CANCELLED", "DECLINED":
		return result.LaunchURL == ""
	case "EXPIRED":
		return result.LaunchURL == "" && !result.ExpiresAt.After(now)
	default:
		return false
	}
}
